/** Sentence returned when an SDK agent-store failure must not reach the caller. */
export const USER_FACING_TURN_FAILURE = "I hit an error while handling your request. Please try again or rephrase.";
/** Stable string for logging / HTTP error bodies. */
export function describeError(error) {
    return error instanceof Error ? error.message : String(error);
}
/** `error.code` when the value is an object that has one. */
export function unknownErrorCode(error) {
    if (typeof error !== "object" || error === null || !("code" in error)) {
        return undefined;
    }
    return error.code;
}
/** Primitive text. Objects do not become `[object Object]`. */
export function plainText(value) {
    if (typeof value === "string") {
        return value;
    }
    if (typeof value === "number" || typeof value === "boolean" || typeof value === "bigint") {
        return String(value);
    }
    if (Array.isArray(value)) {
        return value.map((item) => plainText(item)).join(",");
    }
    return "";
}
export function describeErrorCode(error) {
    if (typeof error === "object" && error !== null && "code" in error) {
        const numericCode = error.code;
        if (numericCode === 1) {
            return "canceled";
        }
        if (numericCode === 14) {
            return "unavailable";
        }
        if (numericCode === 2) {
            return "unknown";
        }
    }
    if (typeof error === "object" &&
        error !== null &&
        "name" in error &&
        error.name === "AbortError") {
        return "ABORT_ERR";
    }
    if (typeof error !== "object" || error === null || !("code" in error)) {
        return undefined;
    }
    const code = error.code;
    return typeof code === "string" && code.length <= 64 ? code : undefined;
}
